{
  "name": "Benchmark Simple Reconciliation",
  "version": 1,
  "datasets": [
    "BM_SIMPLE_GL",
    "BM_SIMPLE_BANK"
  ],
  "rules": [
    {
      "id": "EXACT_REF_AMT_DATE",
      "type": "exact",
      "datasets": [
        "BM_SIMPLE_GL",
        "BM_SIMPLE_BANK"
      ],
      "keys": [
        {
          "type": "text",
          "match_mode": "exact",
          "fields": {
            "BM_SIMPLE_GL": "reference",
            "BM_SIMPLE_BANK": "bank_reference"
          }
        },
        {
          "type": "amount",
          "match_mode": "exact",
          "fields": {
            "BM_SIMPLE_GL": "amount",
            "BM_SIMPLE_BANK": "amount"
          }
        },
        {
          "type": "date",
          "match_mode": "exact",
          "fields": {
            "BM_SIMPLE_GL": "posting_date",
            "BM_SIMPLE_BANK": "value_date"
          }
        }
      ],
      "remarks": "Exact match on Reference, Amount, Date"
    },
    {
      "id": "EXACT_REF_AMT",
      "type": "exact",
      "datasets": [
        "BM_SIMPLE_GL",
        "BM_SIMPLE_BANK"
      ],
      "keys": [
        {
          "type": "text",
          "match_mode": "exact",
          "fields": {
            "BM_SIMPLE_GL": "reference",
            "BM_SIMPLE_BANK": "bank_reference"
          }
        },
        {
          "type": "amount",
          "match_mode": "exact",
          "fields": {
            "BM_SIMPLE_GL": "amount",
            "BM_SIMPLE_BANK": "amount"
          }
        }
      ],
      "remarks": "Exact match on Reference and Amount"
    }
  ]
}
